- name: Backend-only URL encoding, fixed category rail and collection drag
  if: ${{ !cancelled() }}
  run: python tests/ui_text_url_navigation.py 2>&1 | tee artifacts/browser/ui-text-url-navigation.log

if self.path == "/api/url-transform":
    self.send_json(200, {"ok": True, "text": transform_text(payload)})
elif self.path == "/api/workspace":

import {moveCollectionItem} from './collection-move.mjs';
import {bindCollectionDrag} from './collection-drag.mjs';
import {bindUrlMenu} from './url-menu.mjs';

function moveTreeItem(intent) {
  revisionStore.capture();
  const result = moveCollectionItem(workspace, intent, {transfer:(from,to)=>{
    revisionStore.transfer(from,to); studio.transferResponse(from,to);
  }});
  if (!result.changed) return;
  selectedCollectionId = result.target._mpId;
  if (!result.collection) {
    const parents = intent.targetId ? findItem(result.target, intent.targetId)?.parents || [] : [];
    const reveal = new Set([result.target._mpId, ...parents.map(item=>item._mpId), ...(intent.position==='inside'&&intent.targetId?[intent.targetId]:[])]);
    workspace.collapsed = (workspace.collapsed || []).filter(id=>!reveal.has(id));
    studio.captureContext({collectionId:result.target._mpId,parentId:result.parent===result.target?undefined:result.parent?._mpId});
  }
  persist(true); renderAll();
  focusTreeItem(result.collection?result.item._mpId:result.target._mpId,result.collection?undefined:result.item._mpId);
}

const decode = value => {try {return decodeURIComponent(value);} catch {return value;}};
const query = at < 0 ? [] : rest.slice(at + 1).split('&').filter(Boolean).map(part => {
  const equals = part.indexOf('=');
  return {key: decode(equals < 0 ? part : part.slice(0, equals)), value: decode(equals < 0 ? '' : part.slice(equals + 1)), disabled: false};
});
return {base: at < 0 ? rest : rest.slice(0, at), hash, query};

if (u._mpTypedUrl) return u.raw;
const query = u.query.filter(enabled).filter(row => row.key).map(row => `${text(row.key)}=${text(row.value)}`).join('&');
// Only legacy imported path escapes are decoded for readable display. URI
// reserved escapes (%2F, %3F, %23, ...) retain their structural meaning.
let base = u.base;
try {base = decodeURI(base);} catch {}
return base + (query ? `?${query}` : '') + u.hash;

if (!/^https?:///i.test(base)) throw new Error('HTTP / HTTPSに対応しています。');
const pathVariables = {};
// Keep raw text in the transport JSON. The backend encodes path values,
// Unicode and query components exactly once, after resolving structure.
for (const match of base.matchAll(/(?:^|/):([\w-]+)(?=/|[?#]|$)/g)) {
  if (!Object.hasOwn(context.vars, match[1])) throw new Error(`パス変数 :${match[1]} が未設定です。`);
  pathVariables[match[1]] = resolve(context.vars[match[1]]);
}
const query = u.query.filter(enabled).filter(p => p.key).map(p => ({key: resolve(p.key), value: resolve(p.value)}));
const setQueryValue = (key, value) => {
  for (let index = query.length - 1; index >= 0; index--) if (query[index].key === key) query.splice(index, 1);
  query.push({key, value, replace: true});
};

const vertical = root.getAttribute('aria-orientation') === 'vertical';
const previous = vertical ? 'ArrowUp' : 'ArrowLeft', next = vertical ? 'ArrowDown' : 'ArrowRight';
if (!current || ![previous, next, 'Home', 'End'].includes(event.key)) return;
